input.script:
(() => {
  const b = document.querySelector('.dsh-failover-pill');
  if (!b) throw new Error('未找到 .dsh-failover-pill 控件');
  const text = (b.textContent || '').trim();
  if (text !== '智能搜索') throw new Error('可见文案不是「智能搜索」，实际为：' + text);
  if (b.getAttribute('aria-pressed') === null) throw new Error('缺少 aria-pressed 状态属性');
  if (!b.querySelector('svg')) throw new Error('按钮内未找到图标');
  // 形态是药丸按钮而非 Switch：不应存在 switch 角色的控件
  const switchNearby = document.querySelectorAll('[role="switch"], input[type="checkbox"]');
  if (switchNearby.length > 0) {
    throw new Error('输入框附近存在开关式控件（' + switchNearby.length + ' 个）');
  }
  // 不应出现「智能搜索已关」这类状态文案
  const bodyText = document.body.innerText || '';
  for (const phrase of ['智能搜索已关', '智能搜索已开启', '智能搜索已关闭']) {
    if (bodyText.includes(phrase)) throw new Error('出现了状态文案：' + phrase);
  }
  return { text: text, pressed: b.getAttribute('aria-pressed'), hasIcon: true, noSwitchRole: true, noStateText: true };
})()
